contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The single public function: we take no useful parameters except a dummy boolean
    // to satisfy the requirement of having input parameters. The test contract is the deployer/owner.
    function run(bool dummy) public payable {
        require(true);

        // Observe balances before the call
        uint beforeC = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;

        // General rule: when this (the deployer/owner) calls sudicideAnyone it must either revert
        // or, if it succeeds, C's balance becomes zero. That is, it's impossible for the call to succeed
        // and leave a non-zero balance in C.
        assert(reverted || afterC == 0);
    }

    receive() external payable { }
}

